package com.loadoutstudio;
import java.awt.*;import javax.swing.*;import org.junit.Test;import net.runelite.http.api.RuneLiteAPI;import static org.junit.Assert.*;
public class StudioIdentityStyleTest {
 @Test public void stylingDoesNotMutateNativeRuneLiteDefaults()throws Exception{SwingUtilities.invokeAndWait(()->{Color background=UIManager.getColor("Panel.background"),selection=UIManager.getColor("List.selectionBackground");Font font=UIManager.getFont("Label.font");StudioPanel panel=new StudioPanel(new PanelTest.FakeHost(),RuneLiteAPI.GSON);assertEquals(background,UIManager.getColor("Panel.background"));assertEquals(selection,UIManager.getColor("List.selectionBackground"));assertEquals(font,UIManager.getFont("Label.font"));assertEquals(StudioTheme.BACKGROUND,panel.getBackground());panel.dispose();});}
 private static double lum(Color c){double[] v={c.getRed()/255d,c.getGreen()/255d,c.getBlue()/255d};for(int i=0;i<3;i++)v[i]=v[i]<=.04045?v[i]/12.92:Math.pow((v[i]+.055)/1.055,2.4);return .2126*v[0]+.7152*v[1]+.0722*v[2];}
 private static double contrast(Color a,Color b){double x=lum(a),y=lum(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
 @Test public void ownTextAndAccentPairsRemainReadable(){assertTrue(contrast(StudioTheme.TEXT,StudioTheme.BACKGROUND)>=4.5);assertTrue(contrast(StudioTheme.MUTED,StudioTheme.BACKGROUND)>=4.5);assertTrue(contrast(StudioTheme.ACCENT,StudioTheme.SELECTED)>=4.5);assertTrue(contrast(StudioTheme.TEXT,StudioTheme.CONTROL)>=4.5);assertTrue(contrast(StudioTheme.ERROR,StudioTheme.BACKGROUND)>=4.5);}
 @Test public void navigationAndPermanentSupportLabelsFitWithTheirIcons()throws Exception{SwingUtilities.invokeAndWait(()->{for(int width:new int[]{220,260}){StudioPanel panel=new StudioPanel(new PanelTest.FakeHost(),RuneLiteAPI.GSON);panel.setSize(width,900);OwnedGearPanelTest.layout(panel);OwnedGearPanelTest.layout(panel);for(String name:new String[]{"nav:Library","nav:Builder","nav:Wiki","nav:Export","supportCoffee"}){JButton b=(JButton)OwnedGearPanelTest.find(panel,name);int needed=b.getFontMetrics(b.getFont()).stringWidth(b.getText())+b.getInsets().left+b.getInsets().right+b.getIcon().getIconWidth()+b.getIconTextGap();assertTrue(name+" needs "+needed+"px; available="+b.getWidth(),needed<=b.getWidth());assertTrue(b.isVisible());}panel.dispose();}});}
}
